(function () {
  function text(v) { return v == null ? '' : String(v); }
  function pick() {
    for (var i = 0; i < arguments.length; i++) {
      var v = arguments[i];
      if (v != null && v !== '') return v;
    }
    return '';
  }
  function pad(n) { return n < 10 ? '0' + n : String(n); }
  function nowParts(d) {
    return {
      time: d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds()),
      ymd: '' + d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate())
    };
  }
  function mapSex(sex) {
    var s = text(sex);
    if (s === '1' || s === 'M' || s === '男') return 'M';
    if (s === '2' || s === 'F' || s === '女') return 'F';
    return 'O';
  }
  function examType(item) {
    var explicit = pick(item.YLXMLX, item.examType, item.ylxmlx, item.dfiInterfaceCode2);
    if (explicit) return text(explicit);
    var name = text(item.feeItemName);
    if (/CT/i.test(name)) return 'CT';
    if (/MR|核磁/i.test(name)) return 'MR';
    if (/超声|彩超|US/i.test(name)) return 'US';
    if (/DR|X线|胸片|后前位/i.test(name)) return 'DR';
    if (/心电|ECG/i.test(name)) return 'ECG';
    return 'CT';
  }
  function escapeXml(s) {
    return text(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  var item = $.item || {};
  var patient = $.patientInfo || {};
  var doctor = $.doctorInfo || {};
  var now = nowParts(new Date());
  var method = 'examineregister';
  var appID = text($.appID);
  var serviceUri = text($.serviceUri) || 'http://ip:port/Service.asmx';
  if (!appID) throw new Error('请配置莱达 appID（工作流入参 pacsAppId，或改组装报文任务的 appID）');
  var pwd = Crypto.md5(appID + method + now.ymd);
  var data = {
    SQDBH: pick(item.applyId, item.SQDBH),
    SQStatus: pick(item.SQStatus, '50'),
    YLKSDM: pick(item.ddInterfaceCode1, item.executeDeptId, item.idDepart),
    YLKSMC: pick(item.departName, item.executeDeptName),
    BRSFH: pick(patient.identitycard, patient.identityCard),
    BRLX: pick(item.BRLX, '1'),
    BRH: pick(patient.patientCode, patient.hisPatientId),
    BRKH: pick(patient.visitNo, patient.archivesCode, patient.patientCode),
    BRMZH: pick(patient.visitNo, ''),
    BRZYH: '',
    BRBQDM: '',
    BRBQMC: '',
    BRBCH: '',
    BRXM: pick(patient.patientName),
    BRXB: mapSex(patient.sex),
    BRNL: pick(patient.age),
    BRCSDate: text(pick(patient.birthday, '')).substring(0, 10),
    BRLXDZ: pick(patient.address),
    BRLXDH: pick(patient.phone),
    BRZY: pick(patient.orgName, ''),
    SQSF: pick(item.priceYuan, item.factPriceYuan, ''),
    SQYSGH: pick(item.number, doctor.number),
    SQYSXM: pick(item.userName, doctor.userName),
    SQKSDM: pick(item.applyDeptId, ''),
    SQKSMC: pick(item.applyDeptName, '体检中心'),
    SQTime: pick(patient.registertime, now.time),
    SQYY: pick(item.feeItemName, '体检检查'),
    LCBX: pick(item.feeItemName, ''),
    LCZD: pick(item.feeItemName, '体检'),
    DJYSGH: pick(item.number, doctor.number),
    DJYSXM: pick(item.userName, doctor.userName),
    DJTime: now.time,
    JCH: pick(item.applyId, item.idPatientFeeItem),
    YYH: '',
    YLXMDM: pick(item.interfaceCode, item.dfiInterfaceCode1, item.idFeeItem),
    YLXMMC: pick(item.feeItemName),
    YLXMLX: examType(item),
    YLBWDM: pick(item.dfiInterfaceCode3, ''),
    YLBWMC: pick(item.dfiInterfaceCode4, ''),
    YLSBDM: pick(item.dfiInterfaceCode5, ''),
    YLSBMC: ''
  };
  var dataXml = XML.stringify('Data', data);
  var soap = '<?xml version="1.0" encoding="utf-8"?>'
    + '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:tem="http://tempuri.org/">'
    + '<soapenv:Header/>'
    + '<soapenv:Body><tem:Invoke>'
    + '<tem:appID>' + escapeXml(appID) + '</tem:appID>'
    + '<tem:pwd>' + escapeXml(pwd) + '</tem:pwd>'
    + '<tem:method>' + method + '</tem:method>'
    + '<tem:data><![CDATA[' + dataXml + ']]></tem:data>'
    + '</tem:Invoke></soapenv:Body></soapenv:Envelope>';
  return {
    soapXml: soap,
    pwd: pwd,
    serviceUri: serviceUri,
    applyId: data.SQDBH,
    idPatientFeeItem: text(item.idPatientFeeItem),
    medTechRequestId: text(item.applyId)
  };
})()

(function () {
  function text(v) {
    if (v == null) return '';
    if (typeof v === 'object') {
      if (v['#text'] != null) return String(v['#text']);
      return '';
    }
    return String(v);
  }
  function localName(k) {
    var s = String(k);
    var i = s.indexOf(':');
    return i >= 0 ? s.slice(i + 1) : s;
  }
  function walk(node, name) {
    if (node == null || typeof node !== 'object') return null;
    var keys = Object.keys(node);
    for (var i = 0; i < keys.length; i++) {
      if (localName(keys[i]) === name) return node[keys[i]];
    }
    for (var j = 0; j < keys.length; j++) {
      var found = walk(node[keys[j]], name);
      if (found != null) return found;
    }
    return null;
  }
  var body = $.body;
  var parsed = (typeof body === 'string' && body.trim()) ? XML.parse(body) : body;
  var result = walk(parsed, 'InvokeResult') || parsed;
  var code = text(walk(result, 'code'));
  var message = text(walk(result, 'message'));
  var httpOk = Number($.statusCode) >= 200 && Number($.statusCode) < 300;
  var ok = code ? (code === '200') : httpOk;
  return {
    ok: ok,
    code: ok ? '200' : (code || '-1'),
    message: message || (ok ? '成功' : '失败'),
    applyId: $.applyId,
    idPatientFeeItem: $.idPatientFeeItem,
    medTechRequestId: $.medTechRequestId,
    statusCode: $.statusCode
  };
})()

(function () {
  function asArray(value) {
    if (value == null) return [];
    if (Array.isArray(value)) return value;
    if (typeof value.size === 'function' && typeof value.get === 'function') {
      var list = [];
      for (var i = 0; i < value.size(); i++) list.push(value.get(i));
      return list;
    }
    return [value];
  }
  function pick(obj, key) {
    if (obj == null) return null;
    if (typeof obj.get === 'function') {
      var gv = obj.get(key);
      if (gv != null) return gv;
    }
    return obj[key];
  }
  function appendUnique(target, items) {
    asArray(items).forEach(function (item) {
      if (!item) return;
      var exists = target.some(function (existing) {
        return pick(existing, 'medTechRequestId') === pick(item, 'medTechRequestId')
          && pick(existing, 'sourceId') === pick(item, 'sourceId');
      });
      if (!exists) target.push(item);
    });
  }
  function toResultItem(item, type) {
    return {
      applyId: pick(item, 'applyId'),
      idPatientFeeItem: pick(item, 'idPatientFeeItem'),
      medTechRequestId: pick(item, 'applyId'),
      sourceId: pick(item, 'applyId'),
      serviceProviderType: type
    };
  }
  function parseBody(body) {
    if (!body) return {};
    if (typeof body === 'string') {
      try { return JSON.parse(body); } catch (e) { return { message: body }; }
    }
    return body;
  }

  var merged = [];
  var failures = [];
  var splitSummary = $.splitSummary || {};
  var pacsItems = asArray(pick(splitSummary, 'pacsItems'));
  var ecgItems = asArray(pick(splitSummary, 'ecgItems'));

  var pacsLoop = $.pacsLoop || {};
  Object.keys(pacsLoop).forEach(function (key) {
    if (!/^\d+$/.test(key)) return;
    var parsed = pick(pacsLoop[key] || {}, 'parse_pacs_resp_ref') || {};
    var ok = pick(parsed, 'ok') === true || pick(parsed, 'ok') === 'true';
    if (ok) {
      appendUnique(merged, [toResultItem(parsed, 'PACS')]);
    } else {
      failures.push({
        branch: 'PACS',
        iteration: key,
        code: pick(parsed, 'code'),
        message: pick(parsed, 'message'),
        statusCode: pick(parsed, 'statusCode')
      });
    }
  });

  if (ecgItems.length > 0) {
    var ecgStatus = Number($.ecgStatusCode);
    var ecgBody = parseBody($.ecgBody);
    var code = pick(ecgBody, 'code');
    var ok = ecgStatus >= 200 && ecgStatus < 300 && (code == null || String(code) === '200' || code === 200);
    if (ok) {
      appendUnique(merged, ecgItems.map(function (item) { return toResultItem(item, 'ECG'); }));
    } else {
      failures.push({
        branch: 'ECG',
        statusCode: $.ecgStatusCode,
        code: code,
        message: pick(ecgBody, 'message') || pick(ecgBody, 'msg'),
        body: $.ecgBody
      });
    }
  }

  return {
    returnCode: failures.length === 0 ? '200' : '500',
    errorMessage: failures.length === 0 ? '成功' : ('部分调用失败: ' + failures.length),
    data: merged,
    pacsItemCount: pacsItems.length,
    ecgItemCount: ecgItems.length,
    skippedItemCount: pick(splitSummary, 'skippedItemCount') || 0,
    failures: failures
  };
})()
